class Database {
	private static readonly char DBSEP = '\t';
	private static readonly char EOL = '\n';

	protected Map<PredicateFile, Collection<List<string>>> contents;
	protected bool everCleared;

	public Database() {
		contents = new(typeof(PredicateFile));
		foreach (PredicateFile predicateFile in EnumSet.allOf(typeof(PredicateFile)))
			contents.put(predicateFile, new HashSet<List<string>>());
		// contents.put(predicateFile, new ArrayList<List<String>>());
		everCleared = false;
	}

	public void writeFile(Collection<List<string>> contents, PredicateFile predicateFile, string directory)
    {
		Writer w = predicateFile.getWriter(new File(directory), ".facts", everCleared);
		foreach (List<string> record in {
			writeRecord(w, record);
		}
		w.flush();
		w.close();
	}

	public void writeFacts(string directory, bool writeAll)
    {
		int k = Runtime.getRuntime().availableProcessors() * 2 - 1;
		ExecutorService es = Executors.newFixedThreadPool(k);
		foreach (PredicateFile predicateFile in EnumSet.allOf(typeof(PredicateFile))) {
			if (!writeAll && predicateFile.name().startsWith("TYPE_")) {
				continue;
			}
			es.execute(() => {
				try {
					writeFile(this.contents.get(predicateFile), predicateFile, directory);
				} catch (Exception e) {
					// System.out.println(e);
					ghidra.util.Msg.info(this, e);
					foreach (java.lang.StackTraceElement st in e.getStackTrace()) {
						ghidra.util.Msg.info(this, st);
					}
				}
			});
		}

		es.shutdown();
		try {
			while (!es.awaitTermination(30, TimeUnit.SECONDS))
				;
		} catch (Exception e) {
			// System.out.println(e);
			ghidra.util.Msg.info(this, e);
			foreach (java.lang.StackTraceElement st in e.getStackTrace()) {
				ghidra.util.Msg.info(this, st);
			}
		}

		this.clear(writeAll);
	}

	private void writeRecord(Writer writer, List<string> record)
    {
		bool first = true;
		foreach (string col in record) {
			if (!first) {
				writer.write(DBSEP);
			}
			writeColumn(writer, col);
			first = false;
		}
		writer.write(EOL);
	}

	private void writeColumn(Writer writer, string column)
    {
		// Quote some special characters.
		char QUOTE = '\"';
		char SLASH = '\\';
		char TABCH = '\t';
		for (int i = 0; i < column.length(); i++) {
			char c = column.charAt(i);
			switch (c) {
			case QUOTE:
				writer.write("'");
				break;
			case SLASH:
				writer.write('\\');
				writer.write('\\');
				break;
			case EOL:
				writer.write('\\');
				writer.write('n');
				break;
			case TABCH:
				writer.write('\\');
				writer.write('t');
				break;
			default:
				writer.write(c);
			}
		}
	}

	public void add(PredicateFile predicateFile, params string[] args) {
		this.contents.get(predicateFile).add(Arrays.asList(args));
	}

	public void merge(Database other) {
		foreach (Map.Entry<PredicateFile, Collection<List<string>>> entry in other.contents.entrySet()) {
			this.contents.get(entry.getKey()).addAll(entry.getValue());
		}

	}

	public void clear(bool clearAll) {
		foreach (PredicateFile predicateFile in EnumSet.allOf(typeof(PredicateFile))) {
			if (!clearAll && predicateFile.name().startsWith("TYPE_")) {
				continue;
			}
			contents.put(predicateFile, new HashSet<List<string>>());
		}
		everCleared = true;
	}
}


class ItemCounter {
    private ConcurrentHashMap<string, Integer> seenItems = new();
    private AtomicInteger counter = new AtomicInteger(3);

    public int getUniqueNumber(string item) {
        // Check if the item has been seen
        return seenItems.computeIfAbsent(item, key => counter.incrementAndGet());
    }
}

