	private Dictionary<string, PredicateFile> componentPredicates = new Dictionary<string, PredicateFile>();
	private Map<HighVariable, VarnodeAST> extraGlobals = new Dictionary<HighVariable, VarnodeAST>();
	private Writer debug;
